import { Prisma } from '@prisma/client';
import { Request } from 'express';
import { prisma } from '../../lib/prisma.js';
import { AppError } from '../../utils/app_error.js';
import { JwtPayloadType } from '../../utils/JWT.js';
import { assertCanWriteOrgResource, resolveCallerOrgContext } from '../../utils/org_scope.js';

// aexa-frontend#922: AI-suggested-risk lifecycle (dismiss / per-site
// dismissed history / previously-dismissed marking on re-analysis).
//
// RiskSuggestion.risk_id is regenerated by aexa-ai on every analysis run,
// so it cannot be used as a stable identity for a suggestion across
// separate POST /ai/analyze-site-risks calls. Instead this fingerprints a
// suggestion by its (normalized title, normalized category) pair, which the
// AI reproduces near-identically across repeated runs against the same
// site. The frontend independently computes the same fingerprint
// client-side (src/utils/aiSuggestionFingerprint.ts) to match fresh
// suggestions against this endpoint's response without a round trip per
// suggestion -- the two implementations must stay byte-for-byte in sync.
//
// Normalization: trim each field, lowercase it, collapse any run of
// internal whitespace to a single space, then strip any literal "::" a
// field itself contains (so e.g. title="A::B"/category="C" can never
// collide with title="A"/category="B::C" -- both would otherwise normalize
// to "a::b::c") before joining title and category with "::".
const normalize = (value: string): string =>
  value.trim().toLowerCase().replace(/\s+/g, ' ').replace(/::/g, ':');

export const buildSuggestionFingerprint = (title: string, category: string): string =>
  `${normalize(title)}::${normalize(category)}`;

// Read-only site lookup, org-scoped via resolveCallerOrgContext alone --
// used by get_site_suggestion_states. Deliberately does NOT call
// assertCanWriteOrgResource: viewing dismissed-suggestion history is a read,
// and gating it behind write permission would 403 VIEWER/LIGHT_USER roles
// who can otherwise see everything else about the site (found in review --
// resolveCallerAndSite below was originally shared across both read and
// write paths, which silently broke history-viewing for those roles).
const resolveCallerAndSiteForRead = async (req: Request, siteId: string) => {
  const user = req.user as JwtPayloadType;
  const ctx = await resolveCallerOrgContext(user.accountId);

  const site = await prisma.site.findUnique({
    where: { id: siteId, org_account_id: ctx.organizationId },
  });
  if (!site) {
    throw new AppError('Site not found', 404);
  }

  return { user, ctx, site };
};

// Shared by dismiss/mark-imported (both mutate state): resolves the
// caller's org context, requires write permission, and verifies the site
// belongs to that org (mirrors ai.service.ts's analyze_site_risks_with_ai
// site lookup).
const resolveCallerAndSite = async (req: Request, siteId: string) => {
  const user = req.user as JwtPayloadType;
  const ctx = await resolveCallerOrgContext(user.accountId);
  assertCanWriteOrgResource(ctx);

  const site = await prisma.site.findUnique({
    where: { id: siteId, org_account_id: ctx.organizationId },
  });
  if (!site) {
    throw new AppError('Site not found', 404);
  }

  return { user, ctx, site };
};

interface SuggestionPayload {
  siteId: string;
  suggestion: {
    title: string;
    category: string;
    [key: string]: unknown;
  };
}

const upsert_suggestion_state = async (req: Request, status: 'DISMISSED' | 'IMPORTED') => {
  const { siteId, suggestion } = req.body as SuggestionPayload;
  const { user, ctx } = await resolveCallerAndSite(req, siteId);

  const fingerprint = buildSuggestionFingerprint(suggestion.title, suggestion.category);

  const result = await prisma.aiSuggestionState.upsert({
    where: { siteId_fingerprint: { siteId, fingerprint } },
    create: {
      siteId,
      orgAccountId: ctx.organizationId,
      fingerprint,
      title: suggestion.title,
      category: suggestion.category,
      suggestion: suggestion as Prisma.InputJsonValue,
      status,
      actedById: user.accountId,
      actedAt: new Date(),
    },
    update: {
      title: suggestion.title,
      category: suggestion.category,
      suggestion: suggestion as Prisma.InputJsonValue,
      status,
      actedById: user.accountId,
      actedAt: new Date(),
    },
  });

  return result;
};

// Dismisses a suggestion: the user explicitly said "not relevant" and it
// should stop showing up as fresh -- and should show up in the per-site
// dismissed-history view, and be flagged if a later analysis run resuggests
// it (matched by fingerprint, not risk_id).
const dismiss_suggestion = async (req: Request) => upsert_suggestion_state(req, 'DISMISSED');

// Marks a suggestion imported -- called by the frontend right after a
// successful import (fire-and-forget, non-blocking). Kept for data
// completeness (so a re-suggested, already-imported risk isn't
// indistinguishable from one nobody has ever acted on) -- the UI doesn't
// build special "already imported" styling this round, only "previously
// dismissed" (see the ticket's scope). If a previously-dismissed suggestion
// gets re-imported later, this upsert transitions the same row from
// DISMISSED to IMPORTED rather than creating a duplicate.
const mark_suggestion_imported = async (req: Request) => upsert_suggestion_state(req, 'IMPORTED');

// Returns every suggestion-state row for a site (both DISMISSED and
// IMPORTED), most-recently-acted-on first. The frontend filters by status
// client-side: DISMISSED rows drive both the dismissed-history view and the
// "previously dismissed" fingerprint match against freshly analyzed
// suggestions; a single fetch per site-expand serves both needs.
const get_site_suggestion_states = async (req: Request) => {
  const siteId = req.params.siteId as string;
  await resolveCallerAndSiteForRead(req, siteId);

  const rows = await prisma.aiSuggestionState.findMany({
    where: { siteId },
    orderBy: { actedAt: 'desc' },
  });

  return rows;
};

export const ai_suggestion_service = {
  dismiss_suggestion,
  mark_suggestion_imported,
  get_site_suggestion_states,
};
